#define DEFINE_FLOAT_SS_4IMM_N(OP, TYPES, KVALUE, N, D, P_DESC_A, P_DESC_B,  \
                                P_SCALE_D, P_SCALE_A, P_SCALE_B, P_TNSP_A,   \
                                P_TNSP_B, A_PATTERN, B_PATTERN)              \
  template <>                                                                 \
  struct OP<N> {                                                              \
    using Accumulator = float;                                                \
    static constexpr int kK = KVALUE;                                         \
    static constexpr int kD = D;                                              \
    static constexpr uint32_t kARegPattern = A_PATTERN;                       \
    static constexpr uint32_t kSharedWordPattern = B_PATTERN;                 \
    static const char *name() {                                               \
      return "m64n" #N "k" #KVALUE ".f32." TYPES ".ss";                  \
    }                                                                         \
    __device__ __forceinline__ static void exec(                              \
        uint64_t desc_a, uint64_t desc_b, const uint32_t (&)[4],              \
        float (&d)[kMaxAccumulatorRegisters]) {                               \
      int32_t scale_d = 1;                                                    \
      asm volatile(                                                           \
          "{\n"                                                              \
          ".reg .pred p;\n"                                                  \
          "setp.ne.b32 p, " P_SCALE_D ", 0;\n"                              \
          "wgmma.mma_async.sync.aligned.m64n" #N "k" #KVALUE ".f32." TYPES  \
          " {" WGMMA_REG_LIST(D) "}, " P_DESC_A ", " P_DESC_B              \
          ", p, " P_SCALE_A ", " P_SCALE_B ", " P_TNSP_A ", " P_TNSP_B      \
          ";\n"                                                              \
          "}\n"                                                              \
          : WGMMA_FLOAT_D(D)                                                  \
          : "l"(desc_a), "l"(desc_b), "r"(scale_d), "n"(1), "n"(1),        \
            "n"(0), "n"(0));                                                  \
    }                                                                         \
  }

