TEST(WgmmaAsyncLatencyBench, Fa3LikeClockProbe) {
  require_hopper_or_newer();
  int device = 0;
  cudaDeviceProp prop{};
  ASSERT_EQ(cudaGetDevice(&device), cudaSuccess);
  ASSERT_EQ(cudaGetDeviceProperties(&prop, device), cudaSuccess);

  const int blocks = get_env_int("WGMMA_FA3_PROBE_BLOCKS",
                                 std::max(1, prop.multiProcessorCount));
  const int rounds = get_env_int("WGMMA_FA3_PROBE_ROUNDS", 4);
  const int warmup_rounds = get_env_int("WGMMA_FA3_PROBE_WARMUP", 1);
  const std::string prefix = get_env_string(
      "WGMMA_FA3_PROBE_OUT_PREFIX",
      "WgmmaAsyncLatencyBench.Fa3LikeClockProbe");

  std::vector<Fa3LikeResult> results;
  std::vector<Fa3LikeTraceRecord> traces;
  run_and_append_fa3_like_case<1, 0>(prop, blocks, rounds, warmup_rounds,
                                     &results, &traces);
  run_and_append_fa3_like_case<2, 0>(prop, blocks, rounds, warmup_rounds,
                                     &results, &traces);
  run_and_append_fa3_like_case<6, 0>(prop, blocks, rounds, warmup_rounds,
                                     &results, &traces);
  run_and_append_fa3_like_case<12, 0>(prop, blocks, rounds, warmup_rounds,
                                      &results, &traces);
  run_and_append_fa3_like_case<24, 0>(prop, blocks, rounds, warmup_rounds,
                                      &results, &traces);
  run_and_append_fa3_like_case<1, 2600>(prop, blocks, rounds, warmup_rounds,
                                        &results, &traces);
  run_and_append_fa3_like_case<2, 2600>(prop, blocks, rounds, warmup_rounds,
                                        &results, &traces);
  run_and_append_fa3_like_case<6, 2600>(prop, blocks, rounds, warmup_rounds,
                                        &results, &traces);
  run_and_append_fa3_like_case<12, 2600>(prop, blocks, rounds, warmup_rounds,
                                         &results, &traces);
  run_and_append_fa3_like_case<24, 2600>(prop, blocks, rounds, warmup_rounds,
                                         &results, &traces);

  print_fa3_like_results(results);
  write_fa3_like_summary_csv((prefix + ".summary.csv").c_str(), results);
  write_fa3_like_trace_csv((prefix + ".trace.csv").c_str(), traces);
}

